"""Write panel.sksl from panel_spec.py plus the hand-written body.

The generated part is the background, the section bodies and their edges, and
the meters. ``panel_body.sksl`` holds whatever the spec cannot express (here the
gate LED), in the same design pixels.
"""
from __future__ import annotations

import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path[:0] = [str(HERE.parents[1]), str(HERE)]

import bwui.sksl  # noqa: E402
from panel_spec import PANEL  # noqa: E402

HEADER = """\
// Ress-Amp panel shader.
// Generated by gen_panel.py from panel_spec.py + panel_body.sksl; edit those.
// Design pixels: one grid unit is 469/87 px, the whole panel 469 x 286.
// audioLow = (input level 0..1, output level 0..1, gate open 0..1, model 0..1)
"""


def main() -> int:
    body = (HERE / "panel_body.sksl").read_text(encoding="utf-8")
    out = HERE / "panel.sksl"
    out.write_text(bwui.sksl.shader(PANEL, body=body, header=HEADER), encoding="utf-8")
    print(f"wrote {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
